function renderCompilerPromptEvidenceContext(retrieval: BrainRetrievalResult): PromptBrainContextRender {
  const resolution = retrieval.contractVersion === "3" ? retrieval.query.projectResolution : undefined;
  return renderPromptEvidenceContext({
    matchedProject: resolution?.status === "matched" ? resolution.page : undefined,
    includeRoute: true,
    diagnostics: retrieval.contractVersion === "3" ? compilerContextDiagnostics(retrieval) : [],
    temporal: retrieval.query.temporal,
    evidence: retrieval.evidence,
    hardBytes: Number.MAX_SAFE_INTEGER,
  });
}

type BrainRetrievalResult = {
  contractVersion: "1" | "3";
  wiki: {
    alias: string;
    schemaVersion: string;
    runtimeContract: string;
  };
  query: {
    question: string;
    shapes: string[];
    stateView: string;
    resolvedSeeds: string[];
    projectResolution?: BrainProjectResolution;
    temporal?: TemporalQuery;
  };
  evidence: BrainCompiledEvidence[];
  omissions: BrainCompilerOmission[];
  coverage: BrainCompilerCoverage;
  budget: BrainCompilerBudget;
  stop: BrainCompilerStop;
  continuation: Record<string, unknown> | null;
  diagnostics: BrainCompilerDiagnostic[];
  reporting: BrainCompilerReporting;
  selectedPages: string[];
  evidenceCount: number;
  candidateCount: number;
};

type TemporalQuery = Readonly<{
  view: TemporalView;
  request_time: string;
  world_at?: string;
  known_at: string;
  transition?: TemporalTransition;
}>;

