    "## Brain Context",
    ...(input.retrievalLimits ? ["", section("Retrieval limits", input.retrievalLimits)] : []),
    ...(input.includeRoleDisclaimer ? ["", EVIDENCE_ROLE_DISCLAIMER] : []),
